CATCHMENT_M = 750


def catchment() -> Point:
    "The readjustment circle around the south portal, in BNG. Notebook 02 trims it to the Rotherhithe bank."
    return Point(to_bng(SOUTH_PORTAL)).buffer(CATCHMENT_M)

